import{z as i,x as d,o as t,c as A,q as r,j as s,D as E,d as e,s as l,S as B,b as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"AlphaCode","description":"","frontmatter":{"title":"AlphaCode","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/alphacode.md","filePath":"llm/alphacode.md","lastUpdated":1791063341000}'),p={name:"llm/alphacode.md"};function C(h,a,m,c,g,u){const n=d("Mermaid");return t(),A("div",null,[a[2]||(a[2]=r('<h1 id="alphacode" tabindex="-1">AlphaCode <a class="header-anchor" href="#alphacode" aria-label="Permalink to &quot;AlphaCode&quot;">​</a></h1><div class="epigraph"><p>竞赛级代码生成靠的不是一条神程序：先为每题生成最多百万份候选，用题面样例滤掉约 99%，再按在合成输入上的行为聚类，最后在 10 次提交限额里每个簇交一份。</p><footer>—— Li 等，Competition-Level Code Generation with AlphaCode，Science 2022，arXiv:2203.07814</footer></div><p>DeepMind 的 <strong>AlphaCode</strong> 把编程竞赛当作生成系统的评测，而不是把 HumanEval 再刷高一点。模拟参加 Codeforces 近期比赛（每场五千人以上），平均排在前 <strong>54.3%</strong>，大约中位选手；估计 rating 约 <strong>1238</strong>，落在赛前六个月打过比赛的用户的前 28% 叙事里。架构是<strong>非对称编码器–解码器 Transformer</strong>，不是 GPT 式纯解码器。本篇按 arXiv:2203.07814 / <em>Science</em> 写采样管线与结构表；不把 AlphaCode 2 的 Gemini 叙事写进 41B。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><span class="marginnote">术语翻译：pass@k 就是「采样 k 次，至少一次通过全部测试」的概率——k 越大数字越好看。所以比较模型先要对齐 k：Codex 常报 pass@100，AlphaCode 的对应预算是百万级采样再压到 10 次提交，两边的 k 差了好几个数量级。</span><a href="/llm/chen-codex">Codex</a> 已经证明：单测可验证时，多采样能把「偶尔对」变成「k 次里有一对」。竞赛题更硬：题面长、算法新、样例只有几组，隐藏测例会罚错解与超时。选手每题大约 <strong>10 次</strong>提交，不能把百万份都交上去。系统问题因此是三个：如何表示「题面→程序」；如何在可承受的训练成本下把采样做便宜；如何在 10 次限额内挑选彼此不同的算法，而不是交 10 份同一错误。</p><p>公开 GitHub 预训练给句法与库知识，不给竞赛分布。需要 <strong>CodeContests</strong> 一类带官方测例的竞赛数据做微调，并防止评测比赛泄漏进训练。</p><h3 id="编码器读题-解码器写代码" tabindex="-1">编码器读题，解码器写代码 <a class="header-anchor" href="#编码器读题-解码器写代码" aria-label="Permalink to &quot;编码器读题，解码器写代码&quot;">​</a></h3><p>题面平均比题解长约一倍。他们用编码器长度 <strong>1536</strong>、解码器 <strong>768</strong> 的非对称序列；浅编码器、深解码器，训练更省、解题率不掉。表 3：300M 到 <strong>41.1B</strong>。41B：\\(d_{\\mathrm{model}}=6144\\)，查询头 48，KV 头 16，编码器 8 块、解码器 56 块，批 2048，约 205k 步、<strong>967B</strong> token。9B 及以下 KV 头更少。多查询 / 分组 KV 是为了<strong>采样时</strong>减小缓存与更新成本，从而撑起百万级候选，不是为了 HumanEval pass@1。词表 SentencePiece <strong>8000</strong>，GitHub + CodeContests 混合。实现 JAX / Haiku，TPU v4，bfloat16。</p><p><span class="marginnote">41B 与 9B 都用模型并行，每分片 1 个 KV 头。不要把 41B 写成 48 层解码器 GPT。300M 的 4 层编码 / 24 层解码已经显示「浅编码深解码」是家族设计，不是 41B 才有的花招。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预训练：公开 GitHub 代码，下一 token / 翻译式目标把题面与题解当成序列到序列。微调：CodeContests，混合语言（Python、C++ 等）。推理三步：（1）高温、多样化解码，每题最多约 <strong>10^6</strong> 程序；（2）用题面<strong>样例</strong>编译运行，滤掉失败的约 99%；（3）对剩余程序用模型生成的随机输入跑行为，按输出聚类，从不同簇各取代表，最多交 10 份。<span class="marginnote">数字实例：一条题采样 \\(10^6\\) 份，样例过滤掉约 99% 剩约 \\(10^4\\) 份，聚类后每簇交一份、凑满 10 次限额——百万级的头部预算被漏斗三级压缩成十份「彼此不同」的提交。</span>GOLD 一类目标与温度调节用来避免微调后模式崩塌、采样多样性不够。</p><h3 id="提交限额下的-solve-率" tabindex="-1">提交限额下的 solve 率 <a class="header-anchor" href="#提交限额下的-solve-率" aria-label="Permalink to &quot;提交限额下的 solve 率&quot;">​</a></h3><p>论文报 \\(k@n\\) 式解题率：在 \\(n\\) 次采样预算下交 10 份的通过比例。41B 加聚类相对不加聚类有可见提升（例如他们表中 10@100k 一档，聚类后更高）。聚类的假设是：样例都过仍可能在隐藏测例上同错；行为不同的簇更可能覆盖不同算法。这把验证器从「官方隐藏测例」（比赛中不可用）换成「样例 + 合成输入上的等价类」。</p>',13)),(t(),s(B,null,{default:E(()=>[l(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E9%A2%98%E9%9D%A2%201536%22%5D%20--%3E%20ENC%5B%22%E6%B5%85%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20ENC%20--%3E%20DEC%5B%22%E6%B7%B1%E8%A7%A3%E7%A0%81%E5%99%A8%20%E5%86%99%E4%BB%A3%E7%A0%81%20768%22%5D%0A%20%20DEC%20--%3E%20M%5B%22%E6%9C%80%E5%A4%9A%20~1e6%20%E5%80%99%E9%80%89%22%5D%0A%20%20M%20--%3E%20EX%5B%22%E6%A0%B7%E4%BE%8B%E8%BF%87%E6%BB%A4%22%5D%0A%20%20EX%20--%3E%20CL%5B%22%E5%90%88%E6%88%90%E8%BE%93%E5%85%A5%E4%B8%8A%E8%81%9A%E7%B1%BB%22%5D%0A%20%20CL%20--%3E%20TEN%5B%22%E2%89%A410%20%E4%BB%BD%E6%8F%90%E4%BA%A4%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,[e("双向编码器让题面末尾的约束（时间限制、输出格式）能被开头的题意读到，这是纯因果解码器用长前缀硬吃题面时缺的归纳偏置。深解码器承担生成；采样阶段的瓶颈是 KV 缓存，MQA/GQA 把每步写缓存的宽度打下去，百万候选才买得起。过滤是执行语义：编译失败与样例失败的程序在隐藏测例上几乎无价值。聚类是在"),o("strong",null,"不可见测例"),e("出现前，用行为哈希近似「算法多样性」——同一簇交两份往往浪费限额。"),o("span",{class:"marginnote"},"直觉类比：聚类像把一百万张彩票按「号码模式」分组——同组的几乎必同错（样例都对，但隐藏测例会一起挂），每组只挑一张去提交；十个名额要买十种不同的做梦方式，而不是同一张梦买十次。")],-1)),(t(),s(B,null,{default:E(()=>[l(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%A0%B7%E4%BE%8B%E8%BF%87%E6%BB%A4%E5%90%8E%E7%9A%84%E5%80%99%E9%80%89%3Cbr%2F%3E%E7%BA%A6%201e4%20%E4%B8%AA%22%5D%20--%3E%20R%5B%22%E6%A8%A1%E5%9E%8B%E7%94%9F%E6%88%90%E9%9A%8F%E6%9C%BA%E8%BE%93%E5%85%A5%22%5D%0A%20%20R%20--%3E%20H%5B%22%E8%BF%90%E8%A1%8C%E5%BE%97%E8%BE%93%E5%87%BA%20%E2%86%92%20%E8%A1%8C%E4%B8%BA%E5%93%88%E5%B8%8C%22%5D%0A%20%20H%20--%3E%20C%7B%22%E6%8C%89%E8%A1%8C%E4%B8%BA%E5%88%86%E7%B0%87%22%7D%0A%20%20C%20--%3E%7C%22%E5%90%8C%E7%B0%87%EF%BC%9A%E6%A0%B7%E4%BE%8B%E9%83%BD%E5%AF%B9%3Cbr%2F%3E%E4%BD%86%E9%9A%90%E8%97%8F%E6%B5%8B%E4%BE%8B%E5%8F%AF%E8%83%BD%E5%90%8C%E9%94%99%22%7C%20W%5B%22%E4%BA%A4%E4%B8%A4%E4%BB%BD%20%3D%20%E6%B5%AA%E8%B4%B9%E9%99%90%E9%A2%9D%22%5D%0A%20%20C%20--%3E%7C%22%E5%BC%82%E7%B0%87%E5%8F%96%E4%BB%A3%E8%A1%A8%22%7C%20D%5B%2210%20%E4%BB%BD%E8%A6%86%E7%9B%96%2010%20%E7%A7%8D%E6%80%9D%E8%B7%AF%22%5D%0A%20%20W%20--%3E%20LIM%5B%22%E6%A0%B7%E4%BE%8B%E5%BC%B1%20%2F%20%E8%BE%93%E5%85%A5%E4%B8%8D%E8%A6%86%E7%9B%96%E8%BE%B9%E7%95%8C%E6%97%B6%E5%A4%B1%E7%9C%9F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p>54.3% 百分位是<strong>整场比赛规则</strong>下的平均排名，不是 HumanEval pass@1。中位选手叙事成立的前提是：对手是当时那些场次的人类，提交次数被限制，评分含罚时。把它说成「已经达到专家」与原文不符；原文写的是第一次在竞赛平台上有竞争力。</p><h3 id="和-codex、和后来的-rl-代码模型" tabindex="-1">和 Codex、和后来的 RL 代码模型 <a class="header-anchor" href="#和-codex、和后来的-rl-代码模型" aria-label="Permalink to &quot;和 Codex、和后来的 RL 代码模型&quot;">​</a></h3><p>Codex 的验证器是 HumanEval 单测，预算是 pass@100。AlphaCode 的验证器是竞赛样例，预算是百万级再压到 10。后来用编译器反馈做 RL 的代码模型把「过滤」部分搬进训练，推理不必真的采样百万；那是另一条成本曲线。不要把 54.3% 换算成 HumanEval 分数，也不要把 41B 与 GPT-4 的聊天代码混评。</p><p><span class="marginnote">Science 摘要强调「数百万程序再过滤聚类到最多 10 次提交」。工程复述应保留三个数字：百万、99% 滤掉、10 次限额。只写「大模型会做竞赛题」会丢掉这篇真正的系统贡献。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>百万采样的碳与钱不是 IDE 补全可接受的；产品化必须降 \\(n\\) 或把过滤提前到训练。样例弱、或样例与隐藏测例分布差时，过滤过的程序仍会集体错。合成输入若覆盖不到边界，聚类会合并本应分开的算法。Codeforces 模拟场次与训练集时间切割要以论文为准，事后用新场次评会泄漏或分布漂移。编码器–解码器服务栈与纯解码器生态不兼容，复现成本高。</p><p>不要声称「无需搜索的 41B 已经中位」。消融表明规模、采样量、过滤、聚类都在动针。语言以 Python/C++ 为主，不要外推到任意语言竞赛。隐藏测例上的超时、内存与特判，论文用比赛规则处理，本地复现若换评测器会改排名。</p><p><span class="marginnote">出处：Li 等，<em>Competition-Level Code Generation with AlphaCode</em>，arXiv:2203.07814，<em>Science</em> 378, 2022。交互示例见 alphacode.deepmind.com。结构数字以论文 Table 3 为准：41.1B、6144 维、8/56 层、967B token。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AlphaCode 用浅编码深解码的 300M–41B 序列到序列模型做竞赛题，Codeforces 模拟平均前 54.3%。</li><li>推理是百万采样、样例过滤、行为聚类、最多 10 次提交；MQA 为采样服务。</li><li>与 Codex/HumanEval 的 \\(k\\le 100\\) 函数合成不是同一评测。</li><li>中位选手 ≠ 专家；系统贡献在搜索与选择，不单在参数量。</li><li>出处：Li 等，arXiv:2203.07814。</li></ul>',10))])}const b=i(p,[["render",C]]);export{f as __pageData,b as default};
